const MassiveDopInfo=[{name:"StalinVlast1",dop:DopInfo1}]
const DopInfo1=[{id:"StalinVlast1",type:"ИСТОРИЧЕСКИЕ ЛИЧНОСТИ", info:[{id:"stalin",Name:"ИОСИФ ВИССАРИОНОВИЧ СТАЛИН", years:"(1879-1953)",informaion:"Секретарь ЦК и ПРЕДСЕДАТЕЛЬ СОВЕТА МИНИСТРОВ",img:"info/img/People/Stalin.webp"},{id:"Kalinin",Name:"МИХАИЛ ИВАНОВИЧ КАЛИНИН", years:"(1875-1946)",informaion:"ПРЕДСЕДАТЕЛЬ ПРЕЗИДИУМА ВЕРХОВНОГО СОВЕТА СССР",img:"info/img/People/Kalinin.webp"},{id:"beria",Name:"ЛАВРЕНТИЙ ПАВЛОВИЧ БЕРИЯ", years:"(1899-1945)",informaion:"ЗАМЕСТИТЕЛЬ ПРЕДСЕДАТЕЛЯ СОВЕТА МИНИСТРОВ СССР",img:"info/img/People/Beria.webp"},{id:"malenkov",Name:"ГЕОРГИЙ МАКСИМИЛИАНОВИЧ МАЛЕНКОВ", years:"(1901-1988)",informaion:"ЧЛЕН ПОЛИТБИРО ЦК ВКП(б)",img:"info/img/People/Malenkov.webp"},{id:"bulganin",Name:"НИКОЛАЙ АЛЕКСАНДРОВИЧ БУЛГАНИН", years:"(1895-1975)",informaion:"КАНДИДАТ В ЧЛЕНЫ ПОЛИТБИРО ЦК ВКП(б)",img:"info/img/People/Bulganin.webp"},{id:"shvernik",Name:"НИКОЛАЙ МИХАЙЛОВИЧ ШВЕРНИК", years:"(1888-1970)",informaion:"ПРЕДСЕДАТЕЛЬ ПРЕЗИДИУМА ВЕРХОВНОГО СОВЕТА СССР",img:"info/img/People/Shvernik.webp"}]},{id:"StalinTermin1",info:[{id:"1",Text:"Пле́нум ЦК КПСС — пленарное заседание членов и кандидатов в члены Центрального комитета Коммунистической партии Советского Союза, высшего партийного органа СССР, проходящее в период между съездами КПСС."},{id:"2",Text:"Политбюро ЦК КПСС — руководящий орган Коммунистической партии Советского Союза в период между пленумами её Центрального комитета."},{id:"3",Text:"Оргбюро́ (Организационное бюро) ЦК — орган ЦК ВКП(б). Существовал в 1919—1952 годах. Был предназначен для решения кадровых и организационных вопросов."},{id:"4",Text:"Верхо́вный Сове́т СССР — высший орган государственной власти в 1938—1989 годах, высший законодательный и представительный орган Союза Советских Социалистических Республик."},{id:"5",Text:"Совет Министров СССР — высший коллегиальный орган исполнительной и распорядительной государственной власти Союза Советских Социалистических Республик."}]}]

function DopInfoLook(props){
     function CloseLookInfo(){
        const el=document.querySelector(".DopinfoLook")
        el.remove()
    }
    return (<><svg className="CloseButton" width="30" height="30" viewBox="0 0 30 30" fill="none" xmlns="http://www.w3.org/2000/svg" onClick={CloseLookInfo}>
  <path d="M8 8L22 22M8 22L22 8" stroke="#F5DEB3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
</svg><div className="DopinfoLook">{props.DopInfo.map(Dinfo=>(<div key={Dinfo.id}><h1 className="PuntkName">{Dinfo.type}</h1><div className="PS">{Dinfo.type==="ИСТОРИЧЕСКИЕ ЛИЧНОСТИ" ? Dinfo.info.map(P=>(<div className="PuntkDivPeople" key={P.id}><img className="ImgPeople" src={P.img}/><p className="PeopleText">{P.Name}</p><p className="PeopleText">{P.years}</p><p className="PeopleText">{P.informaion}</p></div>)) : Dinfo.info.map(P=>(<p key={P.id} className="Termin">{P.Text}</p>))}</div></div>))}<CloseButton/></div></>)
    function CloseLookInfo(){
        const el=document.querySelector(".DopinfoLook")
        el.remove()
    }}


